int fact(int n) {
    if (n == 0) return 1;
    return n * fact(n - 1);
}
int main() {
    printf("%d", fact(4));
}

def decorator(func):
    def wrapper(*args):
        return func(*args) * 2
    return wrapper

@decorator
def add(a, b):
    return a + b

print(add(3, 4))

